import pandas as pd
# Try multiple formats
def parse_date(s):
    if s is None:
        return pd.NaT
    s = s.strip()
    for fmt in [
        "%B %d, %Y at %I:%M %p",
        "%d %b %Y, %H:%M",
        "%Y-%m-%d %H:%M:%S",
    ]:
        try:
            return pd.to_datetime(s, format=fmt)
        except Exception:
            pass
    # Last resort
    try:
        return pd.to_datetime(s)
    except Exception:
        return pd.NaT

reviews['dt'] = reviews['date'].apply(parse_date)
print("NaT count:", reviews['dt'].isna().sum())
